 # Assuming the column name is "times_appeared"
 pattern = re.compile(r'\s+')  # Matches one or more whitespace characters
 value = value.strip()  # Remove leading and trailing whitespaces
 match = pattern.match(value)
 if not match:
   return value  # If the value is already numeric, no need to change it

 try:
   times_appeared = int(value)  # Convert the string to an integer
 except ValueError:
   return None  # Return None if the conversion fails (indicating that the value is not a number)

 return times_appeared  # Return the cleaned and converted value
return value

